   304→// IsCanonical returns true if the input block root is part of the canonical chain.
   305→func (s *Service) IsCanonical(ctx context.Context, blockRoot [32]byte) (bool, error) {
   306→	s.cfg.ForkChoiceStore.RLock()
   307→	defer s.cfg.ForkChoiceStore.RUnlock()
   308→	// If the block has not been finalized, check fork choice store to see if the block is canonical
   309→	if s.cfg.ForkChoiceStore.HasNode(blockRoot) {
   310→		return s.cfg.ForkChoiceStore.IsCanonical(blockRoot), nil
   311→	}
   312→
   313→	// If the block has been finalized, the block will always be part of the canonical chain.
   314→	return s.cfg.BeaconDB.IsFinalizedBlock(ctx, blockRoot), nil
   315→}
