   317→// HeadPublicKeyToValidatorIndex returns the validator index of the `pubkey` in current head state.
   318→func (s *Service) HeadPublicKeyToValidatorIndex(pubKey [fieldparams.BLSPubkeyLength]byte) (primitives.ValidatorIndex, bool) {
   319→	s.headLock.RLock()
   320→	defer s.headLock.RUnlock()
   321→	if !s.hasHeadState() {
